import (
	"fmt"
)

resp, err := client.CustomerGroups().ListCustomerGroups(ctx, map[string]any{"search_text": "wholesale", "status": "active", "limit": 50}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["customer_groups"].([]any) {
	group := row.(map[string]any)
	fmt.Println(group["id"], group["name"], group["status"])
}
fmt.Println(body["pagination"].(map[string]any)["has_next"])

