create_customer_group.code:
import (
	"fmt"
)

resp, err := client.CustomerGroups().CreateCustomerGroup(ctx, map[string]any{"customer_group": map[string]any{
	"name": "Wholesale Partners", "description": "Trade accounts", "status": "active",
	"purchase_preference": map[string]any{"minimum_purchase": map[string]any{"enabled": true, "amount": 50}, "on_account_purchase": map[string]any{
		"enabled": true, "max_purchase": map[string]any{"enabled": true, "amount": 500}, "credit_limit": map[string]any{"enabled": true, "amount": 1000},
		"payment_terms": map[string]any{"enabled": true, "terms": "NET_30"}}},
	"tax_configuration": map[string]any{"override_store_tax": true, "tax_exempt": false, "tax_message": "Prices exclude GST",
		"show_prices_with_tax_included": true, "prices_entered_with_tax_included": false, "base_price_rounding": "up"},
	"product_display": map[string]any{"overwrite_default": true, "variation_display_type": "enable_matrix_view",
		"display_parent_image": true, "activate_colour_variation_image": false, "show_selected_variation_value": true,
		"strike_through_out_of_stock": false, "single_click_variation_loading": true, "price_display_method": "highest"}}}, nil)
if err != nil {
	log.Fatal(err)
}
group := resp.Map().(map[string]any)["customer_group"].(map[string]any)
terms := group["purchase_preference"].(map[string]any)["on_account_purchase"].(map[string]any)["payment_terms"].(map[string]any)
fmt.Println(group["id"], group["status"], terms["terms"])

